    /**
     * Method to retrieve the Policy via PolicyFetchOneSummary
     * @param 	summary PolicyFetchOneSummary 
     * @return 	PolicyFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Policy getPolicy( PolicyFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PolicyFetchOneSummary arg cannot be null" );
    	
    	Policy entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Policy
        	// --------------------------------------
        	CompletableFuture<Policy> futureEntity = queryGateway.query(new FindPolicyQuery( new LoadPolicyFilter( summary.getPolicyId() ) ), ResponseTypes.instanceOf(Policy.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Policy with id " + summary.getPolicyId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


